import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("REV-02 submitting with missing documents", () => {
  test(
    "submit is rejected with documents_incomplete and lists the missing kinds",
    { tag: "@REV-02" },
    async ({ apiAs }) => {
      // Arrange: a member creates a draft vendor with a unique name and uploads only a W-9.
      const member = await apiAs("member");
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV02 Vendor"),
          category: "services",
          contact_email: `rev02-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 REV-02 w9 fixture"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Wait for the w9 extraction to finish so the vendor has an extracted document.
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${document.id}`);
            return ((await res.json()) as { status: string }).status;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toBe("extracted");

      // Act
      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert
      expect(submitResponse.status()).toBe(409);
      const body = await submitResponse.json();
      expect(body.error.code).toBe("documents_incomplete");

      const errorPayload = JSON.stringify(body.error);
      expect(errorPayload).toContain("contract");
      expect(errorPayload).toContain("insurance_certificate");
      expect(errorPayload).not.toContain('"w9"');
    },
  );
});
